let daily=[],videos=[],traffic=[],days="28",sortKey="viewCount",sortDir=-1;const REFRESH_MS=20*60*1000,$=s=>document.querySelector(s),fmt=n=>new Intl.NumberFormat("en-IN").format(Math.round(n)),hours=m=>(m/60).toFixed(1),net=r=>r[3]-r[4],sourceNames={YT_SEARCH:"YouTube search",RELATED_VIDEO:"Suggested videos",EXT_URL:"External",SUBSCRIBER:"Subscriptions feed",YT_CHANNEL:"Channel pages",PLAYLIST:"Playlists",NO_LINK_OTHER:"Direct or unknown",NOTIFICATION:"Notifications",END_SCREEN:"End screens"};
async function getJson(url){const r=await fetch(`${url}?t=${Date.now()}`,{cache:"no-store"}),d=await r.json();if(!r.ok||d.error)throw new Error();return d}async function load(){try{const [d,c]=await Promise.all([getJson("data.json"),getJson("content.json")]);daily=d.daily;traffic=d.traffic||[];videos=c.videos.map(v=>({...v,format:/^PT(?:[0-5]?\dS)$/.test(v.duration||"")?"Short":"Video"}));render();renderVideos()}catch(error){console.error(error);$("#periodLabel").textContent="Live data unavailable · retrying automatically"}}
function rows(){if(days==="month"){const m={};daily.forEach(r=>{const k=r[0].slice(0,7);m[k]??=[k,0,0,0,0];for(let i=1;i<5;i++)m[k][i]+=r[i]});return Object.values(m)}return daily.slice(-Number(days))}
function render(){const r=rows(),v=r.reduce((s,x)=>s+x[1],0),m=r.reduce((s,x)=>s+x[2],0),sub=r.reduce((s,x)=>s+net(x),0),avg=v?m*60/v:0;$("#reportCards").innerHTML=[["Views",fmt(v),"Selected period"],["Watch time",hours(m)+" hrs","Estimated minutes watched"],["Subscribers",(sub>=0?"+":"")+fmt(sub),"Net gained"],["Avg. duration",Math.floor(avg/60)+":"+String(Math.round(avg%60)).padStart(2,"0"),"Per view"]].map(x=>`<article class="report-card"><span>${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></article>`).join("");$("#periodLabel").textContent=days==="month"?"Grouped month by month":`Latest ${days}-day data available`;$("#dailyRows").innerHTML=[...r].reverse().map(x=>`<tr><td>${x[0]}</td><td>${fmt(x[1])}</td><td>${hours(x[2])} hrs</td><td>${net(x)>=0?"+":""}${net(x)}</td></tr>`).join("");$("#sourceBars").innerHTML=traffic.length?traffic.slice(0,8).map(x=>`<div class="source-row"><span>${sourceNames[x.source]||x.source.replaceAll("_"," ").toLowerCase()}</span><b>${x.percent.toFixed(1)}%</b><i style="--v:${x.percent}%"></i></div>`).join(""):'<p class="source-note">No traffic-source data available for this period.</p>'}
function renderVideos(){const q=($("#reportSearch").value||"").toLowerCase(),list=videos.filter(v=>v.title.toLowerCase().includes(q)).sort((a,b)=>{let x=a[sortKey]??0,y=b[sortKey]??0;return typeof x==="string"?x.localeCompare(y)*sortDir:(x-y)*sortDir});$("#reportVideos").innerHTML=list.map(v=>`<tr><td><div class="video-cell"><img src="${v.thumbnail}" alt=""><b>${v.title}</b></div></td><td>${fmt(v.viewCount)}</td><td>${fmt(v.likeCount||0)}</td><td>${new Date(v.publishedAt).toLocaleDateString("en-IN")}</td><td><span class="format-pill">${v.format}</span></td></tr>`).join("")}
document.querySelectorAll(".report-range button").forEach(b=>b.onclick=()=>{document.querySelectorAll(".report-range button").forEach(x=>x.classList.remove("active"));b.classList.add("active");days=b.dataset.days;render()});document.querySelectorAll("[data-sort]").forEach(h=>h.onclick=()=>{sortDir=sortKey===h.dataset.sort?-sortDir:-1;sortKey=h.dataset.sort;renderVideos()});$("#reportSearch").oninput=renderVideos;$("#downloadCsv").onclick=()=>{const r=rows(),csv=["Date,Views,Watch time minutes,Subscribers net",...r.map(x=>[x[0],x[1],x[2],net(x)].join(","))].join("\n"),a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv"}));a.download="adhyesha-analytics-report.csv";a.click();URL.revokeObjectURL(a.href)};const menu=$("#menuBtn"),side=$("#sidebar"),scrim=$("#scrim");menu.onclick=()=>{side.classList.toggle("open");scrim.classList.toggle("open")};scrim.onclick=()=>{side.classList.remove("open");scrim.classList.remove("open")};load();setInterval(load,REFRESH_MS);
